#[test]
fn diferencial_e_incremental() {
    for (d, n, esp) in CASOS {
        let dados = de_hex(d);
        let mut o = vec![0u8; *n];
        hash(&dados, &mut o);
        assert_eq!(hex(&o), *esp);
        for corte in [0, dados.len() / 3, dados.len()] {
            let mut h = Blake2b::new(*n);
            h.update(&dados[..corte]);
            h.update(&dados[corte..]);
            let mut o2 = vec![0u8; *n];
            h.finalize(&mut o2);
            assert_eq!(o, o2);
        }
    }
}
